-- evt:brake
RegisterEvent(1, "Deep Line brake", function()
    if not (HasItem(12011)) then
        if IsQBitSet(QBit(110021)) then evt.StatusText("The chain lies slack in the rail bed: the cart is free.") else evt.SimpleMessage("The Deep Line cart is chained to this brake wheel, the chain padlocked through it. The padlock wants a heavy iron key: the clan keeps it in the strongbox of their tally room off the mess hall.") end
        return
    end
    RemoveItem(12011)
    evt.SetDoorState(17, DoorAction.Open)
    SetQBit(QBit(110021))
    evt.SimpleMessage("The clan's brake key opens the padlock. You spin the wheel: the chain drops off the Deep Line cart into the rail bed and the brake comes off. The cart is free: climb in at the buffer stop and it will run down the Deep Line to the Clan King's Deep Mine.")
end, "Deep Line brake")

